// Exercise library expansion — node scripts/expand-exercises.mjs [--write]
//
// The library held 54 unique exercises after de-duplication, and the spread was
// the problem more than the count: 4 chest, 5 arms, 7 back. Someone training a
// push/pull/legs split ran out of the app in week one, which is the point at
// which they go back to Nike Training Club and do not come back.
//
// Entries carry no youtubeId on purpose. The detail screen builds a YouTube
// SEARCH from the exercise name — the stored ids had rotted and were already
// unused — so inventing ids would add nothing but a field that lies.
//
// Idempotent: an id that already exists is skipped, never duplicated.

import { readFileSync, writeFileSync } from 'node:fs';

const stripDrive = (p) => p.replace(/^\/([A-Za-z]:)/, '$1');
const ROOT = stripDrive(new URL('../', import.meta.url).pathname);
const FILE = ROOT + 'src/data/exerciseLibrary.json';
const WRITE = process.argv.includes('--write');

// Compact authoring form — expanded below into the full record shape.
// [id, name, category, muscles[], difficulty, equipment[], minutes, kcal/min,
//  description, instructions[], tips[], commonMistakes[]]
