const data = JSON.parse(readFileSync(FILE, 'utf8'));
const existingIds = new Set(data.map((e) => e.id));
const existingNames = new Set(data.map((e) => e.name.trim().toLowerCase()));

const added = [];
const skipped = [];
for (const ex of NEW) {
  if (existingIds.has(ex.id) || existingNames.has(ex.name.trim().toLowerCase())) {
    skipped.push(ex.name);
    continue;
  }
  existingIds.add(ex.id);
  existingNames.add(ex.name.trim().toLowerCase());
  added.push(ex);
}

const merged = [...data, ...added].sort((a, b) => a.name.localeCompare(b.name));
console.log(`exercises: ${data.length} → ${merged.length}  (+${added.length})`);
if (skipped.length) console.log(`  skipped as already present: ${skipped.join(', ')}`);

if (WRITE) {
  writeFileSync(FILE, JSON.stringify(merged, null, 2) + '\n', 'utf8');
  console.log('written.');
} else {
  console.log('dry run — pass --write to apply.');
}
